package com.procurement.quotationcomparison.specification;import com.procurement.quotationcomparison.entity.*;import org.springframework.data.jpa.domain.Specification;public final class QuotationComparisonSpecification{private QuotationComparisonSpecification(){}public static Specification<QuotationComparison>search(String k,ComparisonMethod m,ComparisonStatus s){return(r,q,b)->{var p=b.conjunction();if(k!=null&&!k.isBlank())p=b.and(p,b.like(b.lower(r.get("comparisonNumber")),"%"+k.toLowerCase()+"%"));if(m!=null)p=b.and(p,b.equal(r.get("comparisonMethod"),m));if(s!=null)p=b.and(p,b.equal(r.get("status"),s));return p;};}}
